<script>
const TRACES = ''' + traces_json + ''';

const annotations = {};
let currentIdx = 0;

function init() {
  // Load saved progress
  const saved = localStorage.getItem('fm_annotations_v1');
  if (saved) {
    try {
      const parsed = JSON.parse(saved);
      Object.assign(annotations, parsed);
    } catch(e) {}
  }
  buildNavBar();
  showTrace(0);
  updateProgress();
}

function buildNavBar() {
  const bar = document.getElementById('navBar');
  bar.innerHTML = '';
  TRACES.forEach((t, i) => {
    const btn = document.createElement('button');
    btn.className = 'nav-btn' + (annotations[t.trace_id] ? ' done' : '') + (i === currentIdx ? ' active' : '');
    btn.textContent = i + 1;
    btn.onclick = () => showTrace(i);
    bar.appendChild(btn);
  });
}

function extractPolicy(excerpt) {
  const match = excerpt.match(/<policy>\\n?([\\s\\S]*?)<\\/policy>/);
  return match ? match[1].trim() : excerpt;
}

function showTrace(idx) {
  currentIdx = idx;
  const t = TRACES[idx];
  const ann = annotations[t.trace_id] || {};
  const policy = extractPolicy(t.policy_clause_excerpt);

  let trajHTML = '';
  for (const msg of t.trajectory) {
    const role = msg.role;
    const content = msg.content || '';
    if (role === 'tool') {
      let formatted = content;
      try { formatted = JSON.stringify(JSON.parse(content), null, 2); } catch(e) {}
      trajHTML += '<div class="message tool"><div class="role">Tool Result</div>' + escapeHtml(formatted) + '</div>';
    } else if (role === 'assistant' && content === '') {
      trajHTML += '<div class="message assistant"><div class="role">Agent (tool call)</div><em>[Tool call executed]</em></div>';
    } else {
      trajHTML += '<div class="message ' + role + '"><div class="role">' + (role === 'user' ? 'Customer' : 'Agent') + '</div>' + escapeHtml(content) + '</div>';
    }
  }

  const display = document.getElementById('traceDisplay');
  display.innerHTML = `
    <div class="trace-card">
      <div class="trace-header">
        <strong>Trace ${idx + 1} / ${TRACES.length}</strong>
        <div class="meta">
          <span class="badge type">${t.ambiguity_type}</span>
          <span class="badge ${t.violation_level}">${t.violation_level}</span>
          <span class="badge" style="background:#f3e5f5;color:#7b1fa2;">${t.model}</span>
          <span style="font-size:11px;color:#999;">${t.clause_id}</span>
        </div>
      </div>
      <div class="policy-section">
        <h3>Policy Clause</h3>
        <div class="policy-text">${escapeHtml(policy)}</div>
      </div>
      <div class="trajectory-section">
        <h3>Conversation Trajectory</h3>
        ${trajHTML}
      </div>
      <div class="annotation-section">
        <h3>Your Annotation</h3>
        <div class="mechanism-buttons">
          ${mechButton('SM', 'Structural Misparse', 'parsed text structure wrong', ann)}
          ${mechButton('GF', 'Gap-Filling', 'invented missing info', ann)}
          ${mechButton('BV', 'Boundary Violation', 'exceeded authorization', ann)}
          ${mechButton('SC', 'Spurious Compliance', 'wrong rule/reading choice', ann)}
          ${mechButton('CR', 'Conservative Refusal', 'refused when should act', ann)}
        </div>
        <div class="form-row">
          <label>Confidence:</label>
          <input type="number" id="conf_${t.trace_id}" min="0" max="1" step="0.1" value="${ann.confidence || ''}" onchange="updateAnnotation('${t.trace_id}')">
        </div>
        <div class="form-row">
          <label>Comments:</label>
          <textarea id="comm_${t.trace_id}" placeholder="1-2 sentence justification..." onchange="updateAnnotation('${t.trace_id}')">${ann.comments || ''}</textarea>
        </div>
      </div>
    </div>`;

  buildNavBar();
}

function mechButton(code, name, desc, ann) {
  const selected = ann.mechanism === code ? ' selected' : '';
  return '<button class="mech-btn' + selected + '" onclick="selectMechanism(\\'' + code + '\\')">' +
    '<span class="label">' + code + '</span>' +
    '<span class="desc">' + desc + '</span></button>';
}

function selectMechanism(code) {
  const t = TRACES[currentIdx];
  if (!annotations[t.trace_id]) annotations[t.trace_id] = {};
  annotations[t.trace_id].mechanism = code;
  updateAnnotation(t.trace_id);
  showTrace(currentIdx);
  autoSave();
}

function updateAnnotation(traceId) {
  const confEl = document.getElementById('conf_' + traceId);
  const commEl = document.getElementById('comm_' + traceId);
  if (!annotations[traceId]) annotations[traceId] = {};
  if (confEl) annotations[traceId].confidence = confEl.value;
  if (commEl) annotations[traceId].comments = commEl.value;
  updateProgress();
  autoSave();
}

function updateProgress() {
  const done = Object.values(annotations).filter(a => a.mechanism).length;
  document.getElementById('progressText').textContent = done + ' / ' + TRACES.length + ' completed';
  buildNavBar();
}

function showPrev() { if (currentIdx > 0) showTrace(currentIdx - 1); }
function showNext() { if (currentIdx < TRACES.length - 1) showTrace(currentIdx + 1); }

function jumpToNextUnannotated() {
  for (let i = 0; i < TRACES.length; i++) {
    const idx = (currentIdx + 1 + i) % TRACES.length;
    if (!annotations[TRACES[idx].trace_id] || !annotations[TRACES[idx].trace_id].mechanism) {
      showTrace(idx);
      return;
    }
  }
  alert('All traces annotated!');
}

function exportCSV() {
  let csv = 'trace_id,clause_id,ambiguity_type,model,violation_level,failure_mechanism,confidence,comments\\n';
  for (const t of TRACES) {
    const ann = annotations[t.trace_id] || {};
    csv += [t.trace_id, t.clause_id, t.ambiguity_type, t.model, t.violation_level,
            ann.mechanism || '', ann.confidence || '', '"' + (ann.comments || '').replace(/"/g, '""') + '"'].join(',') + '\\n';
  }
  const blob = new Blob([csv], {type: 'text/csv'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'annotation_results.csv';
  a.click();
  URL.revokeObjectURL(url);
}

function autoSave() { localStorage.setItem('fm_annotations_v1', JSON.stringify(annotations)); }
function saveLocal() { autoSave(); alert('Progress saved to browser localStorage.'); }
function loadLocal() {
  const saved = localStorage.getItem('fm_annotations_v1');
  if (saved) {
    Object.assign(annotations, JSON.parse(saved));
    showTrace(currentIdx);
    updateProgress();
    alert('Progress loaded.');
  } else {
    alert('No saved progress found.');
  }
}

function toggleGuide() {
  const content = document.getElementById('guideContent');
  const arrow = document.getElementById('guideArrow');
  content.classList.toggle('open');
  arrow.textContent = content.classList.contains('open') ? '▼' : '▶';
}

function escapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

init();
</script>
</body>
</html>'''

